// Bản dịch tiếng Việt của cổ thư, khóa là id đoạn văn. Chỉ để tham khảo, nguyên văn vẫn giữ trong data/.
export const CLASSICS_VI: Record<string, string> = {
  "gsf-1-1": "Tinh diệu Thái Cực là chủ của quần tinh. Tử Vi ngôi đế tọa là bậc tôn quý nhất trong các sao. Thiên Phủ là Lệnh Tinh; Nam Đẩu, Bắc Đẩu có Hóa Lộc, Hóa Quyền, Lệnh Tinh; Tả Phù, Hữu Bật là sao chủ việc tế tự.",
  "gsf-1-2": "Tử Vi là vua, lấy Tả Phù, Hữu Bật làm tể tướng. Thiên Phủ là bề tôi, lấy Lộc Tồn làm kho phủ. Thiên Cơ là thiện, Thiên Lương là phúc ấm, gặp thì cát; Liêm Trinh là tù, Phá Quân là hao, gặp thì hung.",
  "gsf-1-3": "Điều cốt yếu khi xem mệnh là trước hết xem cung Mệnh. Chính tinh của cung Mệnh định cách cục, Tam Phương Tứ Chính định đất dụng võ. Kế đến xem cung Thân; cung Thân định cảnh hậu vận và chỗ quy tựa. Sau nữa xem Đại Hạn, Lưu Niên để định nhịp tiến thoái của cả một đời.",
  "gsf-2-1": "Tử Vi là sao đế tọa, được Phù Bật thì quý, được Xương Khúc thì tú, được Khôi Việt thì có quý nhân phù trì. Tử Vi độc tọa không có phụ tá, dù quý cũng không lâu; được cát tinh ở Tam Phương Tứ Chính hội chiếu mới là đại cách chính tông.",
  "gsf-2-2": "Tử Vi ở Tý, Ngọ là thế quý “Diện Nam Bối Bắc”, chủ đại phú đại quý; Tử Vi ở Sửu, Mùi đồng cung với Phá Quân, chủ cương nghị quyết đoán; Tử Vi ở Dần, Thân đồng cung với Thiên Phủ, gọi là cách “Tử Phủ Đồng Cung”, chủ phẩm hạnh đoan chính, cơm áo đủ đầy.",
  "gsf-2-3": "Tử Vi ở Quan Lộc, không có sát tinh xung phá, ắt làm quan cao; Tử Vi ở Điền Trạch, chủ có tổ nghiệp, lại tự tạo dựng được; Tử Vi ở Phu Thê, chủ phối ngẫu đoan trang, khí chất bất phàm, nhưng nên kết hôn muộn, không nên sớm.",
  "gsf-2-4": "Tử Vi kỵ Không Kiếp, chủ có địa vị mà không có lộc. Tử Vi kỵ cảnh cô quân không phụ tá, chủ như ngọn núi đứng trơ trọi, khó thành đại sự. Tử Vi Hóa Quyền chủ độc đoán, Tử Vi Hóa Khoa chủ danh tiếng, Tử Vi Hóa Kỵ chủ bị người khác kiềm chế.",
  "gsf-3-1": "Thất Sát là tướng tinh, tính cương nghị quyết đoán. Thất Sát thủ Mệnh không thích đồng cung với các cát tinh, một mình đi con đường riêng mới là bản cách. Thất Sát gặp Không Kiếp, chủ cô độc phiêu bạt, sự nghiệp khó thành.",
  "gsf-3-2": "Cách Thất Sát Triều Đẩu: Thất Sát ở Tý, Ngọ, Dần, Thân, cung đối có Tử Vi, Thiên Phủ chiếu, chủ tước lộc vinh xương. Hợp nhất với quân đội, cảnh sát, võ chức, mở mang bờ cõi. Một đời quý khí khó cản, nhưng phải trải rèn luyện mới thành đại khí.",
  "gsf-3-3": "Thất Sát gặp Kình Đà, chủ hình thương, huyết quang; Thất Sát gặp Hỏa Linh, chủ uy vũ cương liệt; Thất Sát gặp Hóa Lộc, chủ một thân võ quý; Thất Sát gặp Hóa Kỵ, trái lại chủ tiêu trầm, sự nghiệp nhiều thất bại.",
  "gsf-4-1": "Ba sao Thất Sát, Phá Quân, Tham Lang hội ở các cung Mệnh, Thiên Di, Tài Bạch, Quan Lộc, gọi là “cách Sát Phá Tham”. Chủ một đời nhiều biến động, không cam bình thường, hợp khởi nghiệp, quân đội, cảnh sát, kinh doanh. Thời trẻ dễ xốc nổi mà thất bại, sau trung niên mới ổn định giữ được cơ nghiệp.",
  "gsf-4-2": "Tam Phương của Sát Phá Tham có Hóa Lộc hoặc Hóa Quyền thì động mà có lực, có thể thành đại sự; nếu sát tinh ở Tam Phương quá nặng (Kình, Đà, Hỏa, Linh cùng chiếu) thì động mà không thành, nên tĩnh thủ.",
  "gsf-5-1": "Bốn sao Thiên Cơ, Thái Âm, Thiên Đồng, Thiên Lương cùng nhập các cung Mệnh, Thiên Di, Tài Bạch, Quan Lộc, gọi là “cách Cơ Nguyệt Đồng Lương”. Chủ người nho nhã, thông tuệ, giỏi mưu tính. Hợp nhất với công chức, học thuật, văn nghệ, y tế, dịch vụ và những ngành cần tích lũy ổn định, không nên đại mạo hiểm, đại đầu cơ.",
  "gsf-5-2": "Cơ Nguyệt Đồng Lương tác lại nhân – người xưa nói người có cách này nên đảm nhiệm công chức, công việc hành chính văn thư, an ổn một đời. Lại hội thêm Xương Khúc, Hóa Khoa thì chủ danh tiếng vang xa. Kỵ nhất là sát tinh quá nhiều, khi ấy trái lại chủ nhiều biến động, khó yên.",
  "gsf-6-1": "Hóa Lộc chủ tài, chủ duyên, chủ biến năng lực thành tiền; Hóa Quyền chủ quyền, chủ quyết đoán, chủ tự mình đảm đương một phương; Hóa Khoa chủ danh, chủ quý nhân, chủ văn thư; Hóa Kỵ chủ bệnh, chủ sát, chủ bài học sâu sắc.",
  "gsf-6-2": "Hóa Lộc nhập Mệnh, nguồn tiền dồi dào; Hóa Quyền nhập Mệnh, gánh được trọng trách; Hóa Khoa nhập Mệnh, danh tiếng vang xa; Hóa Kỵ nhập Mệnh, phải trải rèn luyện mới nên người.",
  "gsf-6-3": "Hóa Kỵ nhập Tài Bạch, chủ tiền đến rồi đi; Hóa Kỵ nhập Quan Lộc, chủ sự nghiệp gặp trắc trở; Hóa Kỵ nhập Phu Thê, chủ hôn nhân nhiều sóng gió; Hóa Kỵ nhập Tử Tức, chủ duyên con cái mỏng hoặc cha mẹ con cái xích mích.",
  "gsf-6-4": "Lộc Tồn và Hóa Lộc cùng hội ở Tam Phương của Mệnh, gọi là “Song Lộc Triều Viên”, chủ giàu sánh Đào Chu; Hóa Khoa và Hóa Quyền cùng hội, gọi là “Khoa Quyền Song Hội”, chủ danh và quyền đều tốt đẹp.",
  "gsf-7-1": "Tả Phù, Hữu Bật là “tướng tinh”, chủ trợ lực, quý nhân; Văn Xương, Văn Khúc là “văn tinh”, chủ thông minh tuấn tú; Thiên Khôi, Thiên Việt là “quý nhân tinh”, chủ lúc then chốt có người phù trì.",
  "gsf-7-2": "Sáu cát tinh cùng hội ở Tam Phương Tứ Chính của cung Mệnh, chủ một đời quý nhân không dứt, nhân duyên rất tốt. Dù mệnh cách bình thường, vẫn có thể nhờ sức Lục Cát mà đạt được sự nghiệp phi phàm.",
  "gsf-7-3": "Phù Bật Giáp Mệnh: Tả Phù, Hữu Bật ở hai cung trước và sau, giáp cung Mệnh, chủ một đời có quý nhân phù trì, gặp khó có người giúp. Tốt nhất là đồng cung với Tử Vi, gọi là cách “Quân Thần Khánh Hội”.",
  "gsf-8-1": "Kình Dương, Đà La là “sát tinh”, chủ huyết quang, thị phi, trở ngại; Hỏa Tinh, Linh Tinh là “táo tinh”, chủ xung động, nóng nảy, thương tai; Địa Không, Địa Kiếp là “Không Vong”, chủ hao tài, hư danh, không thực.",
  "gsf-8-2": "Sát tinh không hẳn đều là hung – sát tinh như đá mài dao, có thể luyện nên sức phá thế mà người thường không có. Thời trẻ dễ xốc nổi tự hại mình, sau trung niên mới có thể hóa sát thành quyền.",
  "gsf-8-3": "Kình Đà Giáp Kỵ: Kình Dương, Đà La giáp cung có sao Hóa Kỵ, chủ đại hung. Năm ấy, Đại Hạn ấy phải đặc biệt cảnh giác huyết quang, kiện tụng và biến cố lớn.",
  "gsf-8-4": "Không Kiếp Giáp Mệnh: Địa Không, Địa Kiếp ở hai cung trước và sau, giáp cung Mệnh, chủ một đời nên theo cái hư, không nên theo cái thực, hợp làm các ngành “phi thực” như văn nghệ, tôn giáo, huyền học, không nên kinh doanh đầu tư.",
  "gsf-9-1": "Cung Mệnh là gốc, Tam Phương là dụng: Tài Bạch chủ nguồn tiền, Quan Lộc chủ sự nghiệp, Thiên Di chủ ngoại duyên. Tam Phương Tứ Chính có cát tinh hội chiếu, mệnh cách mới phát dụng trọn vẹn.",
  "gsf-9-2": "Cung Phu Thê xem khí chất phối ngẫu, cung Tử Tức xem duyên phận con cái, cung Tật Ách xem điểm yếu của cơ thể, cung Thiên Di xem vận khi ra ngoài. Chính tinh và Tứ Hóa của mỗi cung quyết định cát hung, tiến thoái trong lĩnh vực ấy.",
  "gsf-9-3": "Cung Điền Trạch là kho của cải trên lá số, chính tài có giữ được hay không xem ở cung này; cung Phúc Đức là sự hưởng thụ tinh thần, lòng có an hay không xem ở cung này; cung Phụ Mẫu là quan hệ với bậc trên, cũng chủ văn thư khế ước.",
  "gsf-9-4": "Cung Vô Chính Diệu mượn cung đối mà luận – khi một cung không có chính tinh, mượn chính tinh của cung đối để luận việc của cung đó. Như cung Mệnh Vô Chính Diệu thì mượn chính tinh cung Thiên Di để định mệnh cách.",
  "qj-1-1": "Tử Vi Đẩu Số do tổ sư Trần Đoàn truyền lại, vốn lấy Tử Vi làm đế tọa, thống ngự trăm sao. Mỗi sao chủ một việc, có phân biệt miếu, vượng, lợi, hãm, có khác biệt cát hung khi hội chiếu. Người xem mệnh trước hết phải an sao, kế định cung Mệnh, cung Thân, ba là xem cát hung của mười hai cung, bốn là tham khảo phi hóa của Đại Hạn, Lưu Niên.",
  "qj-1-2": "Phép an sao: trước hết lấy can năm để khởi Tử Vi; khi đã định được cung của Tử Vi, các sao khác đều theo phép mà bày vào mười hai cung. Mười bốn chính tinh mỗi sao ở vị trí của mình, Lục Cát, Lục Sát phụ trợ mà vận hành. Một lá số đã định thì muôn tượng đều hiện.",
  "qj-1-3": "Cung Mệnh là gốc, chủ cách cục một đời; cung Thân là phụ, chủ chiều hướng sau tuổi ba mươi. Mệnh Thân phân minh mới biết được đường tiến thoái của một người. Tam Phương Tứ Chính hội chiếu mới biết được đất dụng võ của một người. Mười hai cung mỗi cung chủ một việc, mới thấy được toàn cảnh đời người.",
  "qj-2-1": "Tử Vi là chủ của Bắc Đẩu, thống lĩnh các sao. Tử Vi thuộc Thổ, là sao tôn quý. Trong số là đế tọa, hóa khí là Tôn, chủ trung hậu, có uy nghi, tự đi con đường riêng. Mệnh nam, mệnh nữ đều thích Tử Vi thủ Mệnh, nhưng cần có Tả Phù, Hữu Bật đến triều mới là chính cách.",
  "qj-2-2": "Tử Vi độc tọa cần có Phù Bật, Xương Khúc, Khôi Việt giáp trì mới phát huy tác dụng – Tử Vi đơn độc không nơi nương tựa, dù quý cũng không lâu; được cát tinh ở Tam Phương Tứ Chính hội chiếu mới là đại cách Quân Thần Khánh Hội.",
  "qj-2-3": "Tử Vi nhập Mệnh, anh em có quý khí, tự lập nổi trội, được anh cả giúp đỡ nhiều; Tử Vi ở Tử Tức, con cái có quý khí, nhưng dạy dỗ cần công bằng; Tử Vi ở Phu Thê, phối ngẫu đoan trang, nhưng nên kết hôn muộn, không nên sớm.",
  "qj-2-4": "Tử Vi ở Điền Trạch, chủ có tổ nghiệp lại tự tạo dựng được, nhà đất có thể làm trục chính để làm giàu; Tử Vi ở Phúc Đức, về mặt tinh thần theo đuổi phong cách, lòng tự tôn mạnh; Tử Vi ở Quan Lộc, chủ đại phú quý, nên ở ngôi cao.",
  "qj-3-1": "Thiên Phủ thuộc Thổ, là Lệnh Tinh của Nam Đẩu, chủ kho lộc. Thiên Phủ độc tọa chủ phẩm hạnh đoan chính, cơm áo không lo. Thiên Phủ đồng cung với Tử Vi gọi là “Tử Phủ Đồng Cung”, chủ tôn quý. Thiên Phủ thích nhất gặp Lộc Tồn, gọi là “Song Lộc Triều Viên”, chủ đại phú.",
  "qj-3-2": "Thái Âm là chính tinh của Trung Thiên, thuộc Thủy. Thái Âm miếu vượng chủ điền trạch, phú quý; lạc hãm chủ lao lực, bôn ba. Mệnh nữ có Thái Âm là cát nhất, chủ xinh đẹp hiền thục. Thái Âm ở Hợi, Tý chủ đại phú, ở Ngọ, Mùi thì giảm lực.",
  "qj-3-3": "Tham Lang là sao đào hoa, dục vọng, thuộc Mộc thuộc Thủy. Tham Lang chủ đa tài nghệ, giao du rộng. Tham Lang gặp Hỏa Tinh gọi là “cách Hỏa Tham”, gặp Linh Tinh gọi là “cách Linh Tham”, đều chủ hoạnh phát về thiên tài. Nhưng Tham Lang kỵ Không Kiếp, chủ hào nhoáng không thực.",
  "qj-3-4": "Cự Môn thuộc Thủy, hóa khí là Ám, chủ khẩu thiệt thị phi. Cự Môn là sao khẩu tài, hợp luật sư, giáo viên, truyền thông. Cự Môn Hóa Lộc chủ “lấy lời nói sinh tài”, Hóa Kỵ thì khẩu thiệt, kiện tụng không dứt. Cự Môn kỵ nhất là đồng cung với Thái Dương ở hai cung Sửu, Mùi, gọi là “Nhật Nguyệt Phản Bối”.",
  "qj-3-5": "Thiên Tướng thuộc Thủy, hóa khí là Ấn, là sao phụ tá. Thiên Tướng trung hậu thật thà, hợp hành chính, thư ký, pháp vụ. Thiên Tướng không thích độc tọa, tốt nhất đồng cung với Tử Vi hoặc Liêm Trinh, mượn uy nghi của sao ấy mà thành việc.",
  "qj-3-6": "Thiên Lương thuộc Thổ, hóa khí là Ấm, là sao của người già. Thiên Lương chủ thiện lương, từ bi, cô khắc, hóa giải. Thiên Lương hợp pháp luật, y học, giáo dục, tôn giáo. Thiên Lương Hóa Khoa chủ danh tiếng, Hóa Lộc trái lại hư phù.",
  "qj-4-1": "Tử Vi thuộc Thổ, đã luận ở Quyển 2.",
  "qj-4-2": "Thiên Cơ thuộc Mộc, hóa khí là Thiện, là sao trí tuệ. Thiên Cơ chủ thông minh, cơ biến, hiếu động. Thiên Cơ nhập Mệnh, tư duy nhanh nhạy, hợp tư vấn, hoạch định, văn giáo. Thiên Cơ kỵ nhất hay đổi thay không có chủ kiến, cần Văn Xương, Văn Khúc hội chiếu mới nên người.",
  "qj-4-3": "Thái Dương thuộc Hỏa, hóa khí là Quý, là sao quý của nam giới. Thái Dương chủ danh dự, công vụ, giao tế. Thái Dương miếu vượng chủ đại quý, lạc hãm thì lao lực mà không được gì. Thái Dương tốt nhất ở các đất Mão, Thìn, Tỵ, Ngọ, rơi vào Tuất, Hợi, Tý, Sửu thì giảm lực.",
  "qj-4-4": "Vũ Khúc thuộc Kim, hóa khí là Tài, là chủ của các tài tinh. Vũ Khúc chủ cương nghị quyết đoán, giỏi quản lý tài chính và kinh doanh. Vũ Khúc Hóa Kỵ chủ phẫu thuật, huyết quang, tai nạn do kim loại. Vũ Khúc ở Sửu, Mùi đồng cung với Thất Sát, gọi là cách “Vũ Khúc Thất Sát”, chủ cương trực, võ quý.",
  "qj-4-5": "Liêm Trinh thuộc Hỏa thuộc Mộc, hóa khí là Tù, là sao đào hoa bậc thứ. Liêm Trinh văn võ kiêm toàn, đa tài nghệ. Liêm Trinh Hóa Kỵ chủ huyết quang, kiện tụng, tranh chấp tình cảm. Liêm Trinh đồng cung với Thiên Tướng là “cách Liêm Tướng”, chủ có tiếng thanh liêm.",
  "qj-4-6": "Phá Quân thuộc Thủy, hóa khí là Hao, là sao phá hoại và đổi mới. Phá Quân chủ khai sáng, biến động, duyên lục thân mỏng. Phá Quân nên dùng chuyên môn kỹ thuật mà đi khắp thiên hạ. Phá Quân Hóa Lộc gọi là “phá rồi mới lập”, chủ trước tan sau tụ.",
  "qj-5-1": "Hóa Lộc chủ nguồn tiền, chủ duyên phận, chủ biến năng lực thành tiền. Hóa Lộc nhập Tam Phương của Mệnh, chủ nguồn tiền dồi dào; Hóa Lộc nhập Tài Bạch, chủ tiền vào tiền ra, chính tài ổn định.",
  "qj-5-2": "Hóa Quyền chủ quyền lực, chủ quyết đoán, chủ gánh vác. Hóa Quyền nhập Mệnh, chủ có thể tự mình đảm đương một phương; Hóa Quyền nhập Quan Lộc, chủ làm chủ được sự nghiệp, nên đi theo đường quản lý hoặc uy tín chuyên môn kỹ thuật.",
  "qj-5-3": "Hóa Khoa chủ danh tiếng, chủ văn thư, chủ quý nhân. Hóa Khoa nhập Mệnh, chủ danh tiếng vang xa; Hóa Khoa nhập Thân, chủ nhờ danh mà được lợi, hợp văn giáo, nghiên cứu, tư vấn.",
  "qj-5-4": "Hóa Kỵ chủ bệnh, chủ sát, chủ bài học sâu sắc. Hóa Kỵ nhập Tam Phương của Mệnh, chủ một đời có “điểm cùn” – đó là bài học sâu nhất trong mệnh cách, vượt qua được thì thành đại trí tuệ. Khoảng tuổi ba mươi là lúc Hóa Kỵ sắc bén nhất.",
  "qj-5-5": "Cách Tử Phủ Đồng Cung: Tử Vi, Thiên Phủ cùng nhập cung Mệnh, chủ phẩm hạnh đoan chính, cơm áo không lo, có tài lãnh đạo. Cần có Tả Phù, Hữu Bật phối hợp mới là đại cách trọn vẹn.",
  "qj-5-6": "Cách Thất Sát Triều Đẩu: Thất Sát tọa Mệnh ở các cung Tý, Ngọ, Dần, Thân, cung đối có Tử Vi, Thiên Phủ chiếu, chủ tước lộc vinh xương – võ chức đại quý, hợp nhất với quân đội, cảnh sát, chính giới hoặc quản lý cấp cao trong doanh nghiệp.",
  "qj-5-7": "Cách Song Lộc Triều Viên: Hóa Lộc, Lộc Tồn cùng hội ở Tam Phương Tứ Chính của cung Mệnh, nguồn tiền tuôn chảy, cơm áo đủ đầy. Người xưa nói “Song Lộc Triều Viên, giàu sánh Đào Chu”, chủ một đời không lo về tiền.",
  "qj-5-8": "Cách Cơ Nguyệt Đồng Lương: bốn sao Thiên Cơ, Thái Âm, Thiên Đồng, Thiên Lương cùng nhập các cung Mệnh, Thiên Di, Tài Bạch, Quan Lộc, chủ người nho nhã, thông tuệ, giỏi mưu tính. Hợp nhất với công chức, học thuật, văn nghệ, y tế, dịch vụ và những ngành cần tích lũy ổn định.",
  "qj-5-9": "Cách Sát Phá Tham: ba sao Thất Sát, Phá Quân, Tham Lang hội ở Mệnh, chủ một đời nhiều biến động, không cam bình thường, hợp khởi nghiệp, quân đội, cảnh sát, kinh doanh, bán hàng. Sau trung niên mới ổn định giữ được cơ nghiệp.",
  "qj-5-10": "Cách Nhật Nguyệt Đồng Cung: Thái Dương, Thái Âm cùng nhập cung Sửu hoặc cung Mùi, chủ có duyên với người khác giới, sự nghiệp thuận lợi, danh tiếng vang xa. Ở cung Sửu lực khá bình, ở cung Mùi lực hơi giảm.",
  "qs-1-1": "Cung Mệnh là gốc rễ của một thân, là then chốt của vạn sự. Cung Mệnh định thì cách cục một đời định. Xem cung Mệnh trước xem chính tinh, kế xem phụ tinh và sát tinh, rồi xem Tứ Hóa và sự hội chiếu của Tam Phương Tứ Chính.",
  "qs-1-2": "Chính tinh cung Mệnh miếu vượng, chủ có ưu thế bẩm sinh, làm việc ít công mà nhiều kết quả; lạc hãm thì chủ có bất lợi bẩm sinh, nhưng trái lại chủ đại thành – người lạc hãm được hai chữ “không cam” thúc đẩy, lại bùng nổ được cú lội ngược dòng mà mệnh cách miếu vượng không làm được.",
  "qs-1-3": "Cung Mệnh gặp Lục Cát Tinh (Tả Phù, Hữu Bật, Văn Xương, Văn Khúc, Thiên Khôi, Thiên Việt), chủ một đời quý nhân không dứt; cung Mệnh gặp Lục Sát Tinh (Kình Dương, Đà La, Hỏa Tinh, Linh Tinh, Địa Không, Địa Kiếp), chủ nhiều sóng gió rèn giũa, nhưng nếu nhẫn nại vượt qua, trái lại thành đại khí.",
  "qs-2-1": "Cung Tài Bạch chủ nguồn tiền, thu nhập và cách quản lý tiền bạc cả đời. Chính tinh cung Tài Bạch khác nhau thì cách kiếm tiền cũng khác nhau: Tử Vi ở Tài Bạch chủ tiền từ quan chức, Vũ Khúc ở Tài Bạch chủ tiền từ thương nghiệp, Thái Âm ở Tài Bạch chủ tiền từ nhà đất, Cự Môn ở Tài Bạch chủ tiền từ tài ăn nói.",
  "qs-2-2": "Cung Tài Bạch Hóa Lộc nhập Mệnh, chủ nguồn tiền dồi dào; cung Tài Bạch Hóa Kỵ, chủ tiền đến rồi đi; cung Tài Bạch gặp Lộc Tồn, chủ tích lũy ổn định; cung Tài Bạch gặp Không Kiếp, chủ hao tài, hư danh.",
  "qs-3-1": "Cung Quan Lộc chủ sự nghiệp, địa vị, thành tựu xã hội. Chính tinh cung Quan Lộc khác nhau thì hướng sự nghiệp cũng khác nhau: Tử Vi ở Quan Lộc nên ở vị trí cao trên nền tảng lớn, Thái Dương ở Quan Lộc nên theo công vụ, danh tiếng, Vũ Khúc ở Quan Lộc nên theo tài chính, thực nghiệp, Liêm Trinh ở Quan Lộc nên văn võ kiêm toàn.",
  "qs-3-2": "Cung Quan Lộc Hóa Quyền nhập Mệnh, chủ có thể tự mình đảm đương một phương; Hóa Lộc nhập Quan Lộc, chủ tiền đến từ nghề nghiệp; Hóa Kỵ nhập Quan Lộc, chủ nhiều sóng gió nơi công việc.",
  "qs-4-1": "Cung Phu Thê chủ khí chất của phối ngẫu và tình trạng hôn nhân. Cung Phu Thê có Tử Vi chủ phối ngẫu đoan trang, có uy quyền, nên kết hôn muộn; cung Phu Thê có Tham Lang chủ phối ngẫu đa tình, nặng đào hoa; cung Phu Thê có Thiên Lương chủ phối ngẫu chín chắn, điềm đạm, lớn tuổi.",
  "qs-4-2": "Cung Phu Thê Hóa Kỵ xung Mệnh, chủ hôn nhân nhiều sóng gió. Cung Phu Thê gặp Lục Sát, cần đặc biệt lưu ý những rèn giũa trong tình cảm. Cung Phu Thê gặp Lục Cát, chủ phối ngẫu là quý nhân.",
  "qs-5-1": "Tứ Hóa là tinh hoa của lá số – Hóa Lộc chủ tài, Hóa Quyền chủ thế, Hóa Khoa chủ danh, Hóa Kỵ chủ bệnh. Cung vị có Tứ Hóa quyết định các mốc sự kiện trọng đại của một đời.",
  "qs-5-2": "Tứ Hóa năm sinh là Tứ Hóa Bản Mệnh, cố định vĩnh viễn; Nghê sư nhấn mạnh sao Tứ Hóa không động, chỉ xem Đại Hạn, Lưu Niên đi đến đâu. Các phép tự hóa, phi hóa theo can cung, cung Lai Nhân của phái Phi Tinh phương Bắc, Nghê sư không chủ trương dùng.",
  "qs-5-3": "Hóa Lộc nhập Tam Phương Tứ Chính của Mệnh: nguồn tiền ổn định, duyên rộng, năng lực có thể biến thành tiền. Hóa Lộc nhập Phu Thê: hôn nhân ngọt ngào. Hóa Lộc nhập Quan Lộc: sự nghiệp và nguồn tiền tương ứng.",
  "qs-5-4": "Hóa Kỵ nhập Tam Phương Tứ Chính của Mệnh: một đời có bài học sâu sắc, nên đối mặt chứ không nên trốn tránh. Hóa Kỵ nhập Phu Thê: hôn nhân nhiều rèn giũa. Hóa Kỵ nhập Quan Lộc: sự nghiệp nhiều sóng gió, nhưng qua rèn luyện trái lại thành người có chuyên môn.",
  "qs-6-1": "Bốn sao Thiên Cơ, Thái Âm, Thiên Đồng, Thiên Lương cùng nhập Tam Phương Tứ Chính của Mệnh, gọi là cách Cơ Nguyệt Đồng Lương. Người nho nhã, thông tuệ, giỏi mưu tính, hợp nhất với công chức, học thuật, văn nghệ, y tế, dịch vụ và những ngành cần tích lũy ổn định.",
  "qs-6-2": "Cơ Nguyệt Đồng Lương tác lại nhân – người xưa nói người có cách này nên đảm nhiệm công chức, công việc hành chính văn thư, an ổn một đời. Lại hội thêm Xương Khúc, Hóa Khoa thì chủ danh tiếng vang xa. Kỵ nhất là sát tinh quá nhiều, khi ấy trái lại chủ nhiều biến động, khó yên.",
  "qs-7-1": "Hóa Lộc và Lộc Tồn cùng hội ở Tam Phương Tứ Chính của cung Mệnh, gọi là cách Song Lộc Triều Viên. Người xưa nói “Song Lộc Triều Viên, giàu sánh Đào Chu”, chủ một đời không lo về tiền, thường có cả chính tài lẫn hoạnh tài.",
  "qs-7-2": "Song Lộc Triều Viên kỵ nhất Không Kiếp – Không Kiếp xung vào thì song Lộc thành hư danh. Cần gặp Tả Phù, Hữu Bật hoặc Văn Xương, Văn Khúc mới là chính cách.",
};
